package com.maplenou.support.attachment.application.port;

import java.io.IOException;
import java.io.InputStream;
import java.util.Optional;

/**
 * Where attachment binaries are kept: a private local folder or Cloudinary with authenticated delivery. Keys are
 * generated by the server, never taken from user input. Files are never served directly: downloads go through the
 * authorized API endpoint (BR-046).
 */
public interface BinaryStorage {

    /** Readable content of a stored file. */
    interface Content {
        InputStream open() throws IOException;
    }

    void store(String key, byte[] content, String contentType);

    Optional<Content> load(String key);

    void delete(String key);

    /** "local" or "cloudinary" (diagnostics). */
    String name();
}
